<?php
require_once __DIR__.'/../../includes/layout.php';require_role(['Admin']);check_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  $id=(int)($_POST['id']??0);$action=$_POST['action']??'save';
  if($action==='delete') db()->prepare('DELETE FROM school_faqs WHERE id=?')->execute([$id]);
  else {
   $question=trim((string)($_POST['question']??''));$answer=trim((string)($_POST['answer']??''));$source=trim((string)($_POST['source_label']??''));$published=isset($_POST['published'])?1:0;
   if(!$question||strlen($question)>200||!$answer||strlen($answer)>3000||!$source||strlen($source)>120) throw new InvalidArgumentException('Enter a question (up to 200 characters), answer (up to 3000), and source (up to 120).');
   if(preg_match('/(?:sk-[A-Za-z0-9]{20,}|AIza[A-Za-z0-9_-]{20,}|Bearer\s+\S+|(?:password|api[_ -]?key)\s*[:=]\s*\S+|student123|teacher123|parent123|ADMIN\s*\/\s*ADMIN)/i',$answer)) throw new InvalidArgumentException('Do not publish passwords, access tokens, or provider keys in the assistant knowledge.');
   if($published && !isset($_POST['approved'])) throw new InvalidArgumentException('Confirm that the school has approved this information for the public assistant.');
   if($id) db()->prepare('UPDATE school_faqs SET question=?,answer=?,source_label=?,published=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$question,$answer,$source,$published,$id]);
   else db()->prepare('INSERT INTO school_faqs(question,answer,source_label,published) VALUES(?,?,?,?)')->execute([$question,$answer,$source,$published]);
  }
  log_activity($_SESSION['user_id'],'Assistant knowledge updated','Published answers are limited to school-approved information.');set_flash('success','Assistant knowledge saved.');redirect('knowledge.php');
 } catch(InvalidArgumentException $e){$error=$e->getMessage();}
}
$edit=isset($_GET['edit'])?row('SELECT * FROM school_faqs WHERE id=?',[(int)$_GET['edit']]):null;$form=$error?$_POST:($edit??[]);$items=rows('SELECT * FROM school_faqs ORDER BY id DESC');
render_header('Assistant knowledge'); ?>
<div class="page-title"><div><span class="eyebrow">SCHOOL INFORMATION</span><h1>Assistant knowledge</h1><p>Approve the facts the assistant can use. Draft answers stay private.</p></div></div>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-xl-5"><section class="panel"><h2 class="panel-title"><?= $edit?'Edit answer':'Add a school answer' ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($edit['id']??0) ?>"><label for="faq-question">Student question</label><input id="faq-question" name="question" class="form-control mb-3" value="<?= e($form['question']??'') ?>" maxlength="200" required><label for="faq-answer">Approved answer</label><textarea id="faq-answer" name="answer" class="form-control mb-3" rows="6" maxlength="3000" required><?= e($form['answer']??'') ?></textarea><label for="faq-source">Source / responsible office</label><input id="faq-source" name="source_label" class="form-control mb-3" value="<?= e($form['source_label']??'') ?>" placeholder="e.g. Registrar — published office guidelines" maxlength="120" required><label class="d-block small mb-2"><input type="checkbox" name="published" <?= !empty($form['published'])?'checked':'' ?>> Publish for the assistant</label><label class="d-block small mb-3"><input type="checkbox" name="approved"> I confirm this is school-approved information suitable for public questions.</label><button class="btn btn-primary">Save answer</button><a class="btn btn-link" href="knowledge.php">New answer</a></form></section><section class="panel"><h2 class="panel-title">AI connection</h2><p class="small">The school guide and queue booking work without a model. Generative AI requires a configured provider, model, and server-side key in hosting environment settings. Keys are never shown here or sent to the browser.</p><p class="small text-muted">Do not publish student records, account credentials, private policies, or unconfirmed tuition amounts as FAQs.</p></section></div><div class="col-xl-7"><section class="panel"><h2 class="panel-title">School answers</h2><?php if(!$items):empty_state('No school FAQs yet','Add official requirements, office contact details, and current policies. Until then, the guide only knows the existing portal workflows.');endif;foreach($items as $item): ?><article class="faq-admin-item"><div class="d-flex justify-content-between gap-3"><strong><?= e($item['question']) ?></strong><span class="badge-soft <?= $item['published']?'risk-Low':'risk-Medium' ?>"><?= $item['published']?'Published':'Draft' ?></span></div><p class="small mt-2"><?= nl2br(e($item['answer'])) ?></p><small class="text-muted">Source: <?= e($item['source_label']) ?></small><div class="mt-3"><a class="btn btn-sm btn-outline-primary" href="?edit=<?= e($item['id']) ?>">Edit</a><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger confirm-delete">Delete</button></form></div></article><?php endforeach; ?></section></div></div>
